@startuml

class Song {
  + title : string
  + year : int
  + length : int
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteUrl : string
}

class User {
  + id : int
  + name : string
  + address : string
}

class RegularUser {
}

class BusinessUser {
  + vatNumber : string
}

class Single {
}

class Hit {
  + trackNumber : int
}

class Album {
  + title : string
}

class Suggestion {
}

class PurchasingBehavior {
  + behaviorData : string
}

User <|-- RegularUser
User <|-- BusinessUser

Artist "1" -- "*" Song
Song --|> Single
Song --|> Hit

BusinessUser "1" -- "*" Single
BusinessUser "1" -- "*" Hit

RegularUser "1" -- "*" Single
RegularUser "1" -- "*" Album

Album "1" *-- "1..*" Hit

RegularUser "1" -- "0..*" Suggestion
RegularUser "1" -- "0..*" PurchasingBehavior
Suggestion "*" -- "1" PurchasingBehavior

@enduml

